"""The logs-export-v1 vector: regenerated byte for byte, each report holding
what its case was written to expect, and passed from the file itself."""

from __future__ import annotations

import json
import os
from typing import Any

import pytest

from aweb_logs.export import BundleMalformed, read_witnesses, verify_bundle

from .export_cases import cases
from .export_vector import (
    VECTOR_PATH,
    build_vector,
    bundle_stream,
    lines_stream,
    render,
    report,
)

VECTOR: dict[str, Any] = json.loads(VECTOR_PATH.read_bytes())


def _holds(expected: Any, actual: Any) -> bool:
    """Whether ``actual`` holds everything ``expected`` names: objects by key, lists item by item."""
    if isinstance(expected, dict):
        return isinstance(actual, dict) and all(
            key in actual and _holds(value, actual[key]) for key, value in expected.items()
        )
    if isinstance(expected, list):
        return (
            isinstance(actual, list)
            and len(expected) == len(actual)
            and all(_holds(e, a) for e, a in zip(expected, actual, strict=True))
        )
    return bool(expected == actual)


@pytest.mark.skipif(os.environ.get("LOGS_WRITE_VECTOR") != "1", reason="set LOGS_WRITE_VECTOR=1")
def test_write_vector() -> None:
    VECTOR_PATH.write_bytes(render(build_vector()))


def test_the_vector_regenerates_byte_for_byte() -> None:
    assert VECTOR_PATH.read_bytes() == render(build_vector()), (
        "the committed logs-export vector differs from the regenerated one; "
        "rewrite it only for a reviewed change"
    )


@pytest.mark.parametrize("case", cases(), ids=lambda case: case.name)
def test_each_report_holds_what_its_case_expects(case) -> None:
    assert _holds(case.expect, report(case)), report(case)


@pytest.mark.parametrize("entry", VECTOR["cases"], ids=lambda e: e["name"])
def test_cases_from_the_file(entry: dict[str, Any]) -> None:
    receipts, checkpoints = read_witnesses(lines_stream(entry["witness_lines"]))
    verified = verify_bundle(
        bundle_stream(entry),
        receipt_keys=frozenset(entry["receipt_keys"]),
        checkpoint_keys=frozenset(entry["checkpoint_keys"]),
        witness_receipts=receipts,
        witness_checkpoints=checkpoints,
    )
    assert verified.to_json() == entry["report"]


@pytest.mark.parametrize("entry", VECTOR["malformed"], ids=lambda e: e["name"])
def test_malformed_bundles_from_the_file(entry: dict[str, Any]) -> None:
    with pytest.raises(BundleMalformed) as refused:
        verify_bundle(bundle_stream(entry), receipt_keys=frozenset(), checkpoint_keys=frozenset())
    assert refused.value.line == entry["line"]
